#include "tokenParser.hpp"

#include <algorithm>
#include <cstddef>
#include <exception>
#include <string>

#include "../../../util/b64decoder.hpp"

json parseAccessToken(const std::string& accessToken) {
  // NOTE: There is no need to validate the token here, because it's
  // generated by Trino controller, which does its own authentication
  // to the identity provider that includes validating the token signature.
  // If this driver got a token from the Trino controller, we can just use it.
  //
  // A signed JWT (JWS) has three dot-separated parts, the second being the
  // claims; an encrypted one (JWE) has five and no readable claims; any
  // other token is opaque.
  if (std::ranges::count(accessToken, '.') != 2) {
    return json::object();
  }
  const size_t payloadStart = accessToken.find('.') + 1;
  const size_t payloadEnd   = accessToken.find('.', payloadStart);
  try {
    const json payload = json::parse(fromBase64url(
        accessToken.substr(payloadStart, payloadEnd - payloadStart)));
    return payload.is_object() ? payload : json::object();
  } catch (const std::exception&) {
    return json::object();
  }
}
